import { expect, test, uniqueName } from "../../fixtures";

test("vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ apiAs }) => {
  // Arrange: a vendor that belongs to the Globex tenant
  const globex = await apiAs("otherTenant");
  const created = await globex.post("/api/vendors", {
    data: {
      name: uniqueName("Globex Vendor"),
      category: "software",
      contact_email: `ops-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendorId = (await created.json()).id as string;

  // Act: the Northwind member requests that vendor by id
  const member = await apiAs("member");
  const response = await member.get(`/api/vendors/${vendorId}`);

  // Assert
  expect(response.status(), await response.text()).toBe(404);
  const body = await response.json();
  expect(body.error?.code, JSON.stringify(body)).toBe("vendor_not_found");
});
